// Generated from src/registry/sources/control-ui/recipes/pagination.css by scripts/gen-knob-contracts.ts — run `bun run sync:knobs`.
export const paginationKnobs = [
  "--cui-pagination-link-radius",
  "--cui-pagination-link-background",
  "--cui-pagination-link-hover-background",
  "--cui-pagination-link-foreground",
  "--cui-pagination-link-shadow",
] as const;
export type PaginationKnobStyle = Partial<Record<(typeof paginationKnobs)[number], string>>;

@layer components {
  :where([data-control-family="pagination"][data-slot="root"]) {
    --cui-pagination-link-radius: var(--radius-control);
    --cui-pagination-link-background: transparent;
    --cui-pagination-link-hover-background: var(--hover-fill);
    --cui-pagination-link-foreground: var(--foreground);
    --cui-pagination-link-shadow: none;
  }
  :where([data-control-family="pagination"][data-slot="content"]) {
    gap: calc(var(--spacing) * 1);
  }

  :where([data-control-family="pagination"][data-slot="link"]) {
    gap: calc(var(--spacing) * 1);
    padding-inline: calc(var(--spacing) * 2.5);
    --_pagination-link-border-color: transparent;
    border-radius: var(--cui-pagination-link-radius);
    background: var(--cui-pagination-link-background);
    box-shadow:
      inset 0 0 0 1px var(--_pagination-link-border-color),
      var(--cui-pagination-link-shadow);
    color: var(--cui-pagination-link-foreground);
    font-variant-numeric: tabular-nums;
  }

  :where([data-control-family="pagination"][data-slot="link"][data-active="true"]) {
    --cui-pagination-link-background: var(--control-fill);
    --_pagination-link-border-color: var(--border);
    --cui-pagination-link-shadow: var(--shadow-sm);
  }

  @media (hover: hover) {
    :where([data-control-family="pagination"][data-slot="link"]:hover:not([aria-disabled="true"])) {
      background: var(--cui-pagination-link-hover-background);
    }
  }

  :where([data-control-family="pagination"][data-slot="link"][aria-disabled="true"]) {
    opacity: var(--disabled-opacity);
  }

  :where([data-control-family="pagination"][data-slot="link"]:has(> svg:first-child)) {
    padding-inline-start: calc(var(--spacing) * 2);
  }

  :where([data-control-family="pagination"][data-slot="link"]:has(> svg:last-child)) {
    padding-inline-end: calc(var(--spacing) * 2);
  }

  :where([data-control-family="pagination"][data-slot="ellipsis"]) {
    color: var(--muted-foreground);
  }

  @media (pointer: coarse) {
    :where([data-control-family="pagination"][data-slot="link"]) {
      position: relative;
    }

    :where([data-control-family="pagination"][data-slot="link"])::after {
      content: "";
      position: absolute;
      inset: 50% 50%;
      translate: -50% -50%;
      inline-size: 100%;
      block-size: max(100%, var(--touch-target));
    }
  }
}

@property --cui-pagination-link-radius {
  syntax: "<length-percentage>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-pagination-link-background {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-pagination-link-hover-background {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-pagination-link-foreground {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-pagination-link-shadow {
  syntax: "*";
  inherits: true;
}

import { ChevronLeft, ChevronRight, MoreHorizontal } from "lucide-react";
import type { ComponentProps, CSSProperties } from "react";

import type { PaginationKnobStyle } from "@/components/control-ui/knob-contracts/pagination-knobs";
import { cn } from "@/components/control-ui/lib/cn";

export type PaginationEllipsisProps = Omit<ComponentProps<"span">, "style" | "children"> & {
  label?: string;
  style?: CSSProperties & PaginationKnobStyle;
};

export type PaginationLinkProps = Omit<
  ComponentProps<"a"> & {
    isActive?: boolean;
    disabled?: boolean;
  },
  "style"
> & { style?: CSSProperties & PaginationKnobStyle };

// Links are control-shaped by hand rather than importing Button, so pagination installs alone.
export function Pagination({ className, ...props }: ComponentProps<"nav"> & { style?: CSSProperties & PaginationKnobStyle }) {
  return (
    <nav
      aria-label="Pagination"
      data-control-ui="pagination"
      data-control-family="pagination"
      data-slot="root"
      className={cn("mx-auto flex w-full justify-center", className)}
      {...props}
    />
  );
}

export function PaginationContent({ className, ...props }: ComponentProps<"ul"> & { style?: CSSProperties & PaginationKnobStyle }) {
  return (
    <ul
      data-control-ui="pagination"
      data-control-family="pagination"
      data-slot="content"
      className={cn("flex flex-row items-center", className)}
      {...props}
    />
  );
}

export function PaginationItem({ className, ...props }: ComponentProps<"li"> & { style?: CSSProperties & PaginationKnobStyle }) {
  return <li data-control-ui="pagination" data-control-family="pagination" data-slot="item" className={className} {...props} />;
}

const paginationLinkChrome =
  "inline-flex h-[var(--control-h-sm)] min-w-[var(--control-h-sm)] cursor-pointer select-none items-center justify-center whitespace-nowrap aria-disabled:pointer-events-none [&>svg]:size-4 [&>svg]:shrink-0";

export function PaginationLink({ isActive = false, disabled = false, href, className, ...props }: PaginationLinkProps) {
  return (
    <a
      aria-current={isActive ? "page" : undefined}
      data-control-ui="pagination"
      data-control-family="pagination"
      data-slot="link"
      data-control="true"
      data-active={isActive ? "true" : undefined}
      role={disabled ? "link" : undefined}
      aria-disabled={disabled || undefined}
      className={cn(paginationLinkChrome, className)}
      {...props}
      href={disabled ? undefined : href}
    />
  );
}

export function PaginationPrevious({ className, children = "Previous", ...props }: PaginationLinkProps) {
  return (
    <PaginationLink className={className} {...props}>
      <ChevronLeft aria-hidden="true" data-icon-dir="inline" />
      <span>{children}</span>
    </PaginationLink>
  );
}

export function PaginationNext({ className, children = "Next", ...props }: PaginationLinkProps) {
  return (
    <PaginationLink className={className} {...props}>
      <span>{children}</span>
      <ChevronRight aria-hidden="true" data-icon-dir="inline" />
    </PaginationLink>
  );
}

export function PaginationEllipsis({ label = "More pages", className, ...props }: PaginationEllipsisProps) {
  return (
    <span
      data-control-ui="pagination"
      data-control-family="pagination"
      data-slot="ellipsis"
      className={cn("flex h-[var(--control-h-sm)] min-w-[var(--control-h-sm)] items-center justify-center [&>svg]:size-4", className)}
      {...props}
    >
      <MoreHorizontal aria-hidden="true" />
      <span className="sr-only">{label}</span>
    </span>
  );
}
